import inspect

import torch
from flask import Flask, jsonify, request
from transformers import AutoModelForSequenceClassification, AutoTokenizer

MODEL_DIR = "/app/model_cache/sentiment_model"


def _load(cls):
    kwargs = {}
    try:
        params = inspect.signature(cls.from_pretrained).parameters
    except (TypeError, ValueError):
        params = {}
    if "local_files_only" in params or any(
        p.kind == inspect.Parameter.VAR_KEYWORD for p in params.values()
    ):
        kwargs["local_files_only"] = True
    try:
        return cls.from_pretrained(MODEL_DIR, **kwargs)
    except TypeError:
        return cls.from_pretrained(MODEL_DIR)


tokenizer = _load(AutoTokenizer)
model = _load(AutoModelForSequenceClassification)
model.eval()

_id2label = {int(k): str(v).lower() for k, v in model.config.id2label.items()}

app = Flask(__name__)


@app.route("/sentiment", methods=["POST"])
def sentiment():
    data = request.get_json(silent=True)
    if not isinstance(data, dict) or "text" not in data:
        return jsonify({"error": "Missing 'text' field in JSON request body"}), 400
    text = data["text"]
    if not isinstance(text, str) or not text.strip():
        return jsonify({"error": "Field 'text' must be a non-empty string"}), 400

    try:
        inputs = tokenizer(text, return_tensors="pt", truncation=True, max_length=512)
        with torch.no_grad():
            logits = model(**inputs).logits
        probs = torch.nn.functional.softmax(logits, dim=-1)[0]
    except Exception as exc:  # noqa: BLE001
        return jsonify({"error": "Inference failed: %s" % exc}), 400

    scores = {"positive": 0.0, "negative": 0.0}
    for idx, label in _id2label.items():
        key = "positive" if "pos" in label or label == "label_1" else "negative"
        scores[key] = float(probs[idx])

    return jsonify(
        {
            "sentiment": "positive" if scores["positive"] >= scores["negative"] else "negative",
            "confidence": {
                "positive": scores["positive"],
                "negative": scores["negative"],
            },
        }
    )


@app.errorhandler(400)
def bad_request(e):
    return jsonify({"error": "Bad request"}), 400


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, threaded=True)

